from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import multitask, run_task, wait

from theme_music import play_theme_song

# Set up.
prime_hub = PrimeHub()
left_wheel = Motor(Port.F, Direction.COUNTERCLOCKWISE)
right_wheel = Motor(Port.B, Direction.CLOCKWISE)
drive_base = DriveBase(left_wheel, right_wheel, 62.4, 128)

async def subtask():
    for count in range(2):
        await wait(0)
        for sign in [1, -1]:
            await wait(0)
            await wait(1000)
            await drive_base.straight(10 * sign)

async def main():
    drive_base.settings(straight_acceleration=1000)
    drive_base.settings(straight_speed=1000)
    await multitask(
        play_theme_song(prime_hub),
        subtask(),
    )
    for count3 in range(15):
        await wait(0)
        for radius_sign in [1, -1]:
            await wait(0)
            for arc_sign in [1, -1]:
                await wait(0)
                await drive_base.arc(100 * radius_sign, angle=35 * arc_sign)


run_task(main())